func newMixedConfig(opts ...MixedOption) *mixedConfig {
	c := &mixedConfig{
		Fixture: DefaultMixedFixture(),
		clock:   clock.RealClock(),
		without: map[string]struct{}{},
	}
	// Derived: Delete is classified writer, so the interface
	// populates itself and a reader has something to read.
	c.seed = func(ctx context.Context, subject deleteremoves.Mixed) error {
		return subject.Delete(ctx, c.Fixture.Key)
	}
	c.seedIsDerived = true
	for _, o := range opts {
		o(c)
	}
	return c
}

